/// <summary>
/// MPJ_14200_DisputedInvoices
/// Class <c>METDisputedInvoicesEntity</c> holds new and overridden methods
/// </summary>
public class METDisputedInvoicesEntity extends common
{

}

Method.Source:
    /// <summary>
    /// MPJ_14200_DisputedInvoices
    /// Creates CustDispute record
    /// </summary>
    /// <param name = "_entityCtx">EntityCtx</param>
    /// <param name = "_dataSourceCtx">DataSourceCtx</param>
    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        CustTrans       custTrans;
        ReasonTable     reasonTable;
        ReasonTableRef  reasonTableRef;
        CustDispute     custDispute;

        super(_entityCtx, _dataSourceCtx);

        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(METDisputedInvoicesEntity, CustTrans):
                custTrans = this.getCustTrans(this.AccountNum, this.Voucher);
                custDispute = custDispute::findByCustTrans(custTrans.RecId);
                reasonTable    = ReasonTable::find(this.ReasonCode);

                if (reasonTable)
                {
                    ttsbegin;
                    reasonTableRef.Reason = this.ReasonCode;
                    reasonTableRef.ReasonComment = reasonTable.Description;
                    reasonTableRef.insert();
                    ttscommit;
                }
                else if (!reasonTableRef && !reasonTable)
                {
                    throw Error("@MET:DisputedInvoiceEntityValidateReasonCode");
                }

                if (custTrans && reasonTableRef && !custDispute)
                {
                    ttsbegin;
                    custDispute.initValue();
                    custDispute.CustTrans           = custTrans.RecId;
                    custDispute.ReasonTableRef      = reasonTableRef.RecId;
                    custDispute.Status              = CustVendDisputeStatus::Disputed;
                    custDispute.StatusChangedDate   = systemDateGet();
                    custDispute.FollowUpDate        = systemDateGet() + 1;
                    custDispute.AmountCur           = custTrans.AmountCur;
                    custDispute.TransactionBalance  = custTrans.AmountCur;
                    custDispute.TransactionCurrency = custTrans.CurrencyCode;
                    custDispute.insert();
                    ttscommit;
                }
                else if(custDispute)
                {
                    ttsbegin;
                    custDispute.selectForUpdate(true);
                    custDispute.ReasonTableRef      = reasonTableRef.RecId;
                    custDispute.update();
                    ttscommit;
                }
                else
                {
                    throw Error ("@MET:DisputedInvoiceEntityValidateCustTrans");
                }
                
                break;
        }
    }

    /// <summary>
    /// MPJ_14200_DisputedInvoices
    /// Gets trans record
    /// </summary>
    /// <param name = "_accountNum">customer account number</param>
    /// <param name = "_voucher">voucher</param>
    /// <returns></returns>
    public CustTrans getCustTrans(CustAccount _accountNum, Voucher _voucher)
    {
        CustTrans custTrans;

        select firstonly
            AmountCur,
            AmountMST,
            CurrencyCode,
            RecId
        from
            custTrans
        where
            custTrans.accountNum == _accountNum &&
            custTrans.voucher    == _voucher;


        return custTrans;

    }

